//! Parity tests for the `pi_js::vendor::jsdiff` patch functions.
//!
//! `VECTORS` / `APPLY_PATCHES_VECTORS` were generated by running the real `diff@8.0.4` (libesm) under
//! Node 24 on hand-written and seeded-random inputs; each case records the JS result or exception.

use std::sync::Arc;

use pi_js::error::Error;
use pi_js::vendor::jsdiff::patch::line_endings::{
    is_unix, is_unix_array, is_win, is_win_array, unix_to_win, unix_to_win_array, win_to_unix, win_to_unix_array,
};
use pi_js::vendor::jsdiff::{
    AbortableDiffOptions, ApplyPatchOptions, ApplyPatchesOptions, CreatePatchOptions, FILE_HEADERS_ONLY, HeaderOptions,
    INCLUDE_HEADERS, OMIT_HEADERS, PatchInput, StructuredPatch, StructuredPatchHunk, StructuredPatchOptions,
    apply_patch, apply_patches, create_patch, create_patch_abortable, create_two_files_patch,
    create_two_files_patch_abortable, format_patch, format_patch_array, parse_patch, reverse_patch,
    reverse_patch_array, structured_patch, structured_patch_abortable,
};
use serde_json::{Map, Value, json};

fn num(v: &Value) -> f64 {
    match v {
        Value::Null => f64::NAN,
        Value::Number(n) => n.as_f64().expect("number"),
        Value::String(s) => match s.as_str() {
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "NaN" => f64::NAN,
            other => panic!("bad number {other}"),
        },
        other => panic!("bad number {other}"),
    }
}

fn opt_num(o: &Value, key: &str) -> Option<f64> {
    o.get(key).filter(|v| !v.is_null()).map(num)
}

fn opt_bool(o: &Value, key: &str) -> Option<bool> {
    o.get(key).and_then(Value::as_bool)
}

fn opt_str<'a>(o: &'a Value, key: &str) -> Option<&'a str> {
    o.get(key).and_then(Value::as_str)
}

/// `JSON.stringify` of a JS number.
fn jnum(n: f64) -> Value {
    if !n.is_finite() {
        Value::Null
    } else if n.fract() == 0.0 && n.abs() < 9_007_199_254_740_992.0 {
        Value::from(n as i64)
    } else {
        Value::from(n)
    }
}

fn hunk_from_json(h: &Value) -> StructuredPatchHunk {
    StructuredPatchHunk {
        old_start: num(&h["oldStart"]),
        old_lines: num(&h["oldLines"]),
        new_start: num(&h["newStart"]),
        new_lines: num(&h["newLines"]),
        lines: h["lines"]
            .as_array()
            .expect("lines")
            .iter()
            .map(|l| l.as_str().expect("line").to_string())
            .collect(),
    }
}

fn patch_from_json(p: &Value) -> StructuredPatch {
    let s = |k: &str| opt_str(p, k).map(String::from);
    StructuredPatch {
        old_file_name: s("oldFileName"),
        new_file_name: s("newFileName"),
        old_header: s("oldHeader"),
        new_header: s("newHeader"),
        hunks: p["hunks"]
            .as_array()
            .map(|hs| hs.iter().map(hunk_from_json).collect())
            .unwrap_or_default(),
        index: s("index"),
    }
}

fn patches_from_json(v: &Value) -> Vec<StructuredPatch> {
    v.as_array().expect("array").iter().map(patch_from_json).collect()
}

fn patch_to_json(p: &StructuredPatch) -> Value {
    let mut m = Map::new();
    for (k, v) in [
        ("index", &p.index),
        ("oldFileName", &p.old_file_name),
        ("newFileName", &p.new_file_name),
        ("oldHeader", &p.old_header),
        ("newHeader", &p.new_header),
    ] {
        if let Some(v) = v {
            m.insert(k.to_string(), Value::from(v.as_str()));
        }
    }
    let hunks = p
        .hunks
        .iter()
        .map(|h| {
            json!({
                "oldStart": jnum(h.old_start),
                "oldLines": jnum(h.old_lines),
                "newStart": jnum(h.new_start),
                "newLines": jnum(h.new_lines),
                "lines": h.lines,
            })
        })
        .collect();
    m.insert("hunks".to_string(), Value::Array(hunks));
    Value::Object(m)
}

fn patches_to_json(ps: &[StructuredPatch]) -> Value {
    Value::Array(ps.iter().map(patch_to_json).collect())
}

fn header_options(v: Option<&str>) -> Option<HeaderOptions> {
    match v {
        None => None,
        Some("INCLUDE") => Some(INCLUDE_HEADERS),
        Some("FILE_ONLY") => Some(FILE_HEADERS_ONLY),
        Some("OMIT") => Some(OMIT_HEADERS),
        Some(other) => panic!("unknown header options {other}"),
    }
}

fn abortable(o: &Value) -> Option<AbortableDiffOptions> {
    let max_edit_length = opt_num(o, "maxEditLength");
    let timeout = opt_num(o, "timeout");
    (max_edit_length.is_some() || timeout.is_some()).then_some(AbortableDiffOptions {
        max_edit_length,
        timeout,
    })
}

fn structured_options(o: &Value) -> Option<StructuredPatchOptions> {
    (!o.is_null()).then(|| StructuredPatchOptions {
        context: opt_num(o, "context"),
        ignore_whitespace: opt_bool(o, "ignoreWhitespace"),
        strip_trailing_cr: opt_bool(o, "stripTrailingCr"),
    })
}

fn create_options(o: &Value) -> Option<CreatePatchOptions> {
    (!o.is_null()).then(|| CreatePatchOptions {
        context: opt_num(o, "context"),
        ignore_whitespace: opt_bool(o, "ignoreWhitespace"),
        strip_trailing_cr: opt_bool(o, "stripTrailingCr"),
        header_options: header_options(opt_str(o, "headerOptions")),
    })
}

fn apply_options(o: &Value) -> Option<ApplyPatchOptions> {
    (!o.is_null()).then(|| ApplyPatchOptions {
        fuzz_factor: opt_num(o, "fuzzFactor"),
        auto_convert_line_endings: opt_bool(o, "autoConvertLineEndings"),
        compare_line: match opt_str(o, "compareLine") {
            None => None,
            Some("trim") => Some(Arc::new(|_n: f64, line: Option<&str>, _op: &str, content: &str| {
                line.is_some_and(|l| l.trim() == content.trim())
            })),
            Some(other) => panic!("unknown compareLine {other}"),
        },
    })
}

/// The JS outcome of a case: `{"r": ...}` or `{"err": message, "name": name}`.
fn outcome(result: Result<Value, Error>) -> Value {
    match result {
        Ok(r) => json!({ "r": r }),
        Err(e) => json!({ "err": e.message(), "name": e.name() }),
    }
}

fn expected(case: &Value) -> Value {
    match case.get("err") {
        Some(err) => json!({ "err": err, "name": case["name"] }),
        None => json!({ "r": case["r"] }),
    }
}

fn opt_string(v: Option<String>) -> Value {
    v.map_or(Value::Null, Value::from)
}

fn run_case(case: &Value) -> Value {
    let k = case["k"].as_str().expect("k");
    let s = |key: &str| case[key].as_str().expect(key);
    let header = |key: &str| case[key].as_str();
    let o = case.get("o").unwrap_or(&Value::Null);
    match k {
        "structuredPatch" => {
            let (old_name, new_name, a, b) = (s("oldName"), s("newName"), s("a"), s("b"));
            let r = match abortable(o) {
                Some(ab) => structured_patch_abortable(
                    old_name,
                    new_name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    structured_options(o),
                    ab,
                ),
                None => Some(structured_patch(
                    old_name,
                    new_name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    structured_options(o),
                )),
            };
            outcome(Ok(r.as_ref().map_or(Value::Null, patch_to_json)))
        }
        "createTwoFilesPatch" => {
            let (old_name, new_name, a, b) = (s("oldName"), s("newName"), s("a"), s("b"));
            let r = match abortable(o) {
                Some(ab) => create_two_files_patch_abortable(
                    old_name,
                    new_name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    create_options(o),
                    ab,
                ),
                None => Some(create_two_files_patch(
                    old_name,
                    new_name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    create_options(o),
                )),
            };
            outcome(Ok(opt_string(r)))
        }
        "createPatch" => {
            let (name, a, b) = (s("name"), s("a"), s("b"));
            let r = match abortable(o) {
                Some(ab) => create_patch_abortable(
                    name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    create_options(o),
                    ab,
                ),
                None => Some(create_patch(
                    name,
                    a,
                    b,
                    header("oldHeader"),
                    header("newHeader"),
                    create_options(o),
                )),
            };
            outcome(Ok(opt_string(r)))
        }
        "parsePatch" => outcome(parse_patch(s("input")).map(|ps| patches_to_json(&ps))),
        "formatPatch" => {
            let h = header_options(case["h"].as_str());
            let patch = &case["patch"];
            if patch.is_array() {
                outcome(format_patch_array(&patches_from_json(patch), h).map(Value::from))
            } else {
                outcome(Ok(Value::from(format_patch(&patch_from_json(patch), h))))
            }
        }
        "applyPatch" => {
            let source = s("source");
            let patch = &case["patch"];
            let options = apply_options(o);
            let result = match patch {
                Value::String(text) => apply_patch(source, text.as_str(), options),
                Value::Array(_) => apply_patch(source, &patches_from_json(patch), options),
                _ => apply_patch(source, &patch_from_json(patch), options),
            };
            outcome(result.map(|r| r.map_or(Value::Bool(false), Value::from)))
        }
        "reversePatch" => {
            let patch = &case["patch"];
            if patch.is_array() {
                outcome(Ok(patches_to_json(&reverse_patch_array(&patches_from_json(patch)))))
            } else {
                outcome(Ok(patch_to_json(&reverse_patch(&patch_from_json(patch)))))
            }
        }
        other => panic!("unknown case kind {other}"),
    }
}

#[test]
fn patch_functions_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(VECTORS).expect("vectors");
    let mut failures = Vec::new();
    let mut checked = 0;
    for (i, case) in cases.iter().enumerate() {
        if case["k"] == "lineEndings" {
            continue;
        }
        checked += 1;
        let actual = run_case(case);
        let want = expected(case);
        if actual != want {
            failures.push(format!("case {i}: {case}\n  rust: {actual}"));
        }
    }
    assert!(checked > 1000);
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        checked,
        failures.join("\n")
    );
}

#[test]
fn line_ending_functions_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(VECTORS).expect("vectors");
    let mut checked = 0;
    for (i, case) in cases.iter().enumerate().filter(|(_, c)| c["k"] == "lineEndings") {
        checked += 1;
        let patch = &case["patch"];
        if patch.is_array() {
            let ps = patches_from_json(patch);
            assert_eq!(
                patches_to_json(&unix_to_win_array(&ps)),
                case["unixToWin"],
                "case {i} unixToWin"
            );
            assert_eq!(
                patches_to_json(&win_to_unix_array(&ps)),
                case["winToUnix"],
                "case {i} winToUnix"
            );
            assert_eq!(Value::from(is_unix_array(&ps)), case["isUnix"], "case {i} isUnix");
            assert_eq!(Value::from(is_win_array(&ps)), case["isWin"], "case {i} isWin");
        } else {
            let p = patch_from_json(patch);
            assert_eq!(patch_to_json(&unix_to_win(&p)), case["unixToWin"], "case {i} unixToWin");
            assert_eq!(patch_to_json(&win_to_unix(&p)), case["winToUnix"], "case {i} winToUnix");
            assert_eq!(Value::from(is_unix(&p)), case["isUnix"], "case {i} isUnix");
            assert_eq!(Value::from(is_win(&p)), case["isWin"], "case {i} isWin");
        }
    }
    assert!(checked > 10);
}

#[test]
fn apply_patches_matches_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(APPLY_PATCHES_VECTORS).expect("vectors");
    for (i, case) in cases.iter().enumerate() {
        let files = case["files"].as_object().expect("files");
        let mut out: Vec<Value> = Vec::new();
        let options = ApplyPatchesOptions {
            fuzz_factor: None,
            auto_convert_line_endings: None,
            compare_line: None,
            load_file: Box::new(|index: &StructuredPatch| {
                let name = index.old_file_name.as_deref().unwrap_or_default();
                Ok(files[name].as_str().expect("file").to_string())
            }),
            patched: Box::new(|index: &StructuredPatch, content: Option<String>| {
                out.push(json!([
                    index.old_file_name,
                    content.map_or(Value::Bool(false), Value::from)
                ]));
                Ok(())
            }),
        };
        let input = &case["input"];
        let result = match input {
            Value::String(text) => apply_patches(text.as_str(), options),
            _ => apply_patches(&patches_from_json(input), options),
        };
        assert!(result.is_ok(), "case {i}: {result:?}");
        assert!(case["completeErr"].is_null());
        assert_eq!(Value::Array(out), case["out"], "case {i}");
    }
}

#[test]
fn apply_patches_stops_on_callback_error() {
    let patch = "--- a\n+++ a\n@@ -1 +1 @@\n-a\n+b\n--- c\n+++ c\n@@ -1 +1 @@\n-c\n+d\n";
    let mut loaded = Vec::new();
    let result = apply_patches(
        patch,
        ApplyPatchesOptions {
            fuzz_factor: None,
            auto_convert_line_endings: None,
            compare_line: None,
            load_file: Box::new(|index: &StructuredPatch| {
                loaded.push(index.old_file_name.clone());
                Err(Error::msg("load failed"))
            }),
            patched: Box::new(|_: &StructuredPatch, _: Option<String>| Ok(())),
        },
    );
    assert_eq!(result.expect_err("error").message(), "load failed");
    assert_eq!(loaded, vec![Some("a".to_string())]);
}

#[test]
fn apply_patch_accepts_every_patch_input_form() {
    let source = "a\nb\n";
    let text = "@@ -1,2 +1,2 @@\n a\n-b\n+c\n";
    let parsed = parse_patch(text).expect("parse");
    let expected = Some("a\nc\n".to_string());
    assert_eq!(apply_patch(source, text, None).expect("text"), expected);
    assert_eq!(apply_patch(source, &text.to_string(), None).expect("string"), expected);
    assert_eq!(apply_patch(source, &parsed[0], None).expect("patch"), expected);
    assert_eq!(apply_patch(source, &parsed, None).expect("vec"), expected);
    assert_eq!(apply_patch(source, parsed.as_slice(), None).expect("slice"), expected);
    assert_eq!(
        apply_patch(source, PatchInput::Array(&parsed), None).expect("input"),
        expected
    );
}

#[test]
fn format_patch_array_rejects_omitted_headers_for_multiple_files() {
    let patches = parse_patch("--- a\n+++ a\n@@ -1 +1 @@\n-a\n+b\n--- c\n+++ c\n@@ -1 +1 @@\n-c\n+d\n").expect("parse");
    let err = format_patch_array(&patches, Some(OMIT_HEADERS)).expect_err("error");
    assert_eq!(
        err.message(),
        "Cannot omit file headers on a multi-file patch. (The result would be unparseable; how would a tool trying to apply the patch know which changes are to which file?)"
    );
}

